   },
   mistral: {
     name: 'Mistral AI', key: true, openai: true,
     endpoint: 'https://api.mistral.ai/v1/chat/completions',
     models: [
       { id: 'open-mistral-nemo', label: 'Mistral NeMo' },
       { id: 'mistral-small-latest', label: 'Mistral Small' },
