import { readFileSync } from 'node:fs';
import crypto from 'node:crypto';

const B62 = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz';
function ocId(prefix) {
  const packed = Date.now() * 0x1000;
  let tail = '';
  for (const b of crypto.randomBytes(14)) tail += B62[b % 62];
  return prefix + packed.toString(16).padStart(12, '0').slice(-12) + tail;
}
const TOOLS = JSON.parse(readFileSync(new URL('../code/relay/builtin_tools.json', import.meta.url), 'utf8'));
const h = {
  'Content-Type': 'application/json',
  'User-Agent': 'opencode/1.18.31',
  'x-opencode-client': 'cli',
  'x-opencode-project': 'global',
  'x-opencode-session': ocId('ses_'),
  'x-opencode-request': ocId('msg_'),
  Accept: 'application/json, text/event-stream',
};
const body = {
  model: process.argv[2] || 'ling-3.0-flash-fin-free',
  stream: true,
  tool_choice: 'auto',
  tools: TOOLS,
  messages: [
    { role: 'system', content: 'Ты — помощник пользователя приложения VoiceComic (комиксы → озвученное видео). Отвечай по-русски, коротко и по делу.' },
    { role: 'user', content: 'Привет! Ты можешь создать файл README.md в папке проекта?' },
  ],
};
const r = await fetch('https://opencode.ai/zen/v1/chat/completions', { method: 'POST', headers: h, body: JSON.stringify(body), signal: AbortSignal.timeout(90000) });
console.log('status', r.status, r.headers.get('content-type'));
const raw = await r.text();
console.log(raw.slice(0, Number(process.argv[3] || 6000)));

