import { readFileSync } from 'node:fs';
import crypto from 'node:crypto';

const B62 = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz';
function ocId(prefix) {
  const packed = Date.now() * 0x1000;
  let tail = '';
  for (const b of crypto.randomBytes(14)) tail += B62[b % 62];
  return prefix + packed.toString(16).padStart(12, '0').slice(-12) + tail;
}
const ALL = JSON.parse(readFileSync(new URL('../code/relay/builtin_tools.json', import.meta.url), 'utf8'));
const mode = process.argv[2] || 'all'; // all | none | one
const model = process.argv[3] || 'ling-3.0-flash-fin-free';
const h = {
  'Content-Type': 'application/json',
  'User-Agent': 'opencode/1.18.31',
  'x-opencode-client': 'cli',
  'x-opencode-project': 'global',
  'x-opencode-session': ocId('ses_'),
  'x-opencode-request': ocId('msg_'),
  Accept: 'application/json, text/event-stream',
};
const body = {
  model,
  stream: true,
  tool_choice: 'auto',
  messages: [
    { role: 'system', content: 'Ты — помощник пользователя приложения VoiceComic (комиксы → озвученное видео). Отвечай по-русски, коротко и по делу.' },
    { role: 'user', content: 'Привет! Ты можешь создать файл README.md в папке проекта?' },
  ],
};
if (mode === 'all') body.tools = ALL;
if (mode === 'one') body.tools = ALL.filter((t) => t.function.name === 'read');
const r = await fetch('https://opencode.ai/zen/v1/chat/completions', { method: 'POST', headers: h, body: JSON.stringify(body), signal: AbortSignal.timeout(90000) });
const raw = await r.text();
console.log('== mode=' + mode, 'model=' + model, 'status', r.status);
let content = '', toolCalls = 0, usage = null, finish = null;
for (const line of raw.split(/\r?\n/)) {
  const s = line.trim();
  if (!s.startsWith('data:')) continue;
  const p = s.slice(5).trim();
  if (!p || p === '[DONE]') continue;
  try {
    const o = JSON.parse(p);
    if (o.error) { console.log('ERROR-EVENT', JSON.stringify(o.error).slice(0, 200)); continue; }
    if (o.usage) usage = o.usage;
    const d = o.choices && o.choices[0];
    if (!d) continue;
    if (d.delta && d.delta.content) content += d.delta.content;
    if (d.delta && d.delta.tool_calls) toolCalls += d.delta.tool_calls.length;
    if (d.finish_reason) finish = d.finish_reason;
  } catch (_) {}
}
console.log('finish=' + finish, 'tool_call_deltas=' + toolCalls, 'usage=' + JSON.stringify(usage));
console.log('content: ' + content.slice(0, 400));

